/**
 * SQLite-flavored DDL applied by every Zelavis SQLite-compatible adapter
 * (better-sqlite3, bun:sqlite, libSQL).
 *
 * Restricted to features supported by all four dialects so each adapter
 * can apply the same statements without modification.
 */
export declare const SCHEMA_STATEMENTS: readonly ["CREATE TABLE IF NOT EXISTS zv_collections (\n    tenant_id TEXT NOT NULL,\n    name TEXT NOT NULL,\n    created_at TEXT NOT NULL,\n    document_count INTEGER NOT NULL DEFAULT 0,\n    surface TEXT,\n    metadata_json TEXT,\n    PRIMARY KEY (tenant_id, name)\n  )", "CREATE TABLE IF NOT EXISTS zv_events (\n    sequence INTEGER PRIMARY KEY AUTOINCREMENT,\n    event_id TEXT NOT NULL UNIQUE,\n    idempotency_key TEXT,\n    node_id TEXT NOT NULL,\n    tenant_id TEXT NOT NULL,\n    collection_name TEXT NOT NULL,\n    document_id TEXT,\n    type TEXT NOT NULL,\n    revision INTEGER NOT NULL,\n    timestamp TEXT NOT NULL,\n    schema_version INTEGER NOT NULL DEFAULT 1,\n    payload_json TEXT NOT NULL\n  )", "CREATE TABLE IF NOT EXISTS zv_schemas (\n    collection_name TEXT NOT NULL,\n    version INTEGER NOT NULL,\n    fields_json TEXT NOT NULL,\n    is_active INTEGER NOT NULL DEFAULT 0,\n    PRIMARY KEY (collection_name, version)\n  )", "CREATE TABLE IF NOT EXISTS zv_time_series_checkpoints (\n    tenant_id TEXT NOT NULL,\n    series_name TEXT NOT NULL,\n    definition_version TEXT NOT NULL,\n    last_sequence INTEGER NOT NULL DEFAULT 0,\n    updated_at TEXT NOT NULL,\n    PRIMARY KEY (tenant_id, series_name)\n  )", "CREATE TABLE IF NOT EXISTS zv_time_series_points (\n    tenant_id TEXT NOT NULL,\n    series_name TEXT NOT NULL,\n    definition_version TEXT NOT NULL,\n    source_sequence INTEGER NOT NULL,\n    point_index INTEGER NOT NULL,\n    timestamp_ms INTEGER NOT NULL,\n    value REAL NOT NULL,\n    tags_json TEXT,\n    fields_json TEXT,\n    PRIMARY KEY (\n      tenant_id,\n      series_name,\n      definition_version,\n      source_sequence,\n      point_index\n    )\n  )", "CREATE INDEX IF NOT EXISTS zv_events_tenant_sequence_idx\n    ON zv_events (tenant_id, sequence)", "CREATE INDEX IF NOT EXISTS zv_events_stream_idx\n    ON zv_events (tenant_id, collection_name, document_id, sequence)", "CREATE INDEX IF NOT EXISTS zv_schemas_collection_active_idx\n    ON zv_schemas (collection_name, is_active, version)", "CREATE INDEX IF NOT EXISTS zv_time_series_points_lookup_idx\n    ON zv_time_series_points (\n      tenant_id,\n      series_name,\n      definition_version,\n      timestamp_ms,\n      source_sequence,\n      point_index\n    )", "CREATE UNIQUE INDEX IF NOT EXISTS zv_events_tenant_idempotency_idx\n    ON zv_events (tenant_id, idempotency_key)\n    WHERE idempotency_key IS NOT NULL"];
